(function (R) {
  'use strict';
  R.I18n.add('en', {
    // ---- src/events/snow_00_common.js
    'ev.snow_00_common.TALES.dragon.name': 'The Dragon and the Maiden\'s Promise',
    'ev.snow_00_common.TALES.dragon.teller': 'Ingrid',
    'ev.snow_00_common.TALES.dragon.lines': ['Long ago, a young woman carried fire\nup to the peak of blizzards.', 'By the fire, the dragon heard\na human story for the first time.\nUntil the night gave way, she told it.', '-- Every year, I will bring you fire and\nstories. So please, calm the blizzards.', 'The dragon nodded, they say, and spread\nits white wings over the village.'],
    'ev.snow_00_common.TALES.hunter.name': 'The Wolf and the Hunter',
    'ev.snow_00_common.TALES.hunter.teller': 'Olaf',
    'ev.snow_00_common.TALES.hunter.lines': ['Long ago, a hunter found a wolf cub\ncaught in a trap.', 'The hunter freed it from the trap\nand sent it back to its pack.', 'On the night of the great winter blizzard,\nthe wolf pack did not surround the village.\nThey guarded its gate.', 'They were repaying a kindness,\nso the hunter\'s grandson said.'],
    'ev.snow_00_common.TALES.fire_child.name': 'The Child Who Stole Fire',
    'ev.snow_00_common.TALES.fire_child.teller': 'Brenda',
    'ev.snow_00_common.TALES.fire_child.lines': ['Long ago, a child from a freezing village\nstole a single spark from the firebird\'s nest.', 'Hugging the fire to its chest,\nthe child ran home across the snow.', 'Wherever the child passed, the wall of ice\nmelted away into a path.', 'The firebird did not grow angry.\n"Share it," it cried, so they say.'],
    'ev.snow_00_common.GATES.n': 'the north gate',
    'ev.snow_00_common.GATES.e': 'the east gate',
    'ev.snow_00_common.GATES.w': 'the west gate',
    'ev.snow_00_common.skyLine.ret': 'Hey, what\'s "daybreak"?\nGranny said it in\nher sleep.',
    'ev.snow_00_common.skyLine.ret_2': 'Lately the night sky\nlooks a pale violet.\n...It\'s not just me, right?',
    'ev.snow_00_common.skyLine.ret_3': 'Isn\'t the sky a little\nbluer lately?',
    'leads.l_snow_prep.title': 'Preparing the Bonfire Festival',
    'leads.l_snow_prep.text': 'Chief Jorn needs help getting the\nfestival ready: firewood, ice lanterns,\nand an old tale to tell at the fire.',
    'leads.l_snow_prep.from': 'Jorn, Chief of Yule',
    'leads.l_snow_book.title': 'The Blank Storybook',
    'leads.l_snow_book.text': 'The storybook read at the festival\nhas turned completely blank. There\'s\nfaint writing on the last page.',
    'leads.l_snow_book.from': 'Sonja, the firekeeper\'s daughter',
    'leads.l_snow_howl.title': 'Howls in the Blizzard',
    'leads.l_snow_howl.text': 'Night after night, wolf howls\ncreep closer to the village.\nHald the lookout is worried.',
    'leads.l_snow_howl.from': 'Hald, the old lookout',
    'leads.l_snow_peak.title': 'The Solstice Fire to the Peak',
    'leads.l_snow_peak.text': 'The siege is over. I\'ll take a spark\nof the solstice fire up to the summit\nof White Dragon Peak.',
    'leads.l_snow_peak.from': 'Sonja, the firekeeper\'s daughter',
    'leads.l_main_recorder_snow.title': 'A Book Emptied by Copying',
    'leads.l_main_recorder_snow.text': 'At the end of the blank festival book:\n"Copy -- Archive Norden Branch."\nDid copying drain it of its words?',
    'leads.l_main_recorder_snow.from': 'The blank festival book',
    'leads.l_main_recorder_snow.dir': 'North',
    'leads.q_snow_fishing.title': 'The Ice Fishing Contest',
    'leads.q_snow_fishing.text': 'During the festival, there\'s a fishing\ncontest on the frozen pond.\nTalk to Tore at the fishing hut.',
    'leads.q_snow_fishing.from': 'Yule notice board',
    'leads.q_snow_dog.title': 'The Lost Sled Dog',
    'leads.q_snow_dog.text': 'One sled dog ran off toward the\nsnowy woods and never came back.\nBring it home, and the sled can run.',
    'leads.q_snow_dog.from': 'Nils, the sled dog keeper',
    'leads.q_snow_statue.title': 'Snow Sculpting',
    'leads.q_snow_statue.text': 'Liisa, the snow sculptor, is\nlooking for three things to\ndecorate her statue with.',
    'leads.q_snow_statue.from': 'Liisa, the snow sculptor',
    'leads.q_snow_base.title': 'The Children\'s Secret Base',
    'leads.q_snow_base.text': 'Behind the snowbank is the children\'s\nsecret base. Seems you need\na password to get in.',
    'leads.q_snow_base.from': 'Village child',
    'leads.q_snow_lamps.title': 'Lamps Along the Road',
    'leads.q_snow_lamps.text': 'Past Yule\'s east gate, three lanterns\non the Lampkeepers\' Road have gone out.\nShare the solstice fire with them.',
    'leads.q_snow_lamps.from': 'Sonja',
    'leads.q_snow_lamps.dir': 'East',
    'leads.q_pass_bath.title': 'The Frozen Bath Tap',
    'leads.q_pass_bath.text': 'The Pass Inn bath\'s water inlet\nhas frozen solid. A single fire pot\nwould thaw it, they say.',
    'leads.q_pass_bath.from': 'Pass Inn bath attendant',
    'leads.q_snow_ingrid.title': 'The Village Storytellers',
    'leads.q_snow_ingrid.text': 'Three village elders know the old\ntales told at the festival:\nIngrid, Olaf, and Brenda.',
    'leads.q_snow_ingrid.from': 'Jorn',
    'leads.l_opt_icicle.title': 'The Chest in the Ice',
    'leads.l_opt_icicle.text': 'Someone saw a treasure chest\nsealed in ice, in a cave\nin the western cliffs.',
    'leads.l_opt_icicle.from': 'Guest staying in Yule',
    'leads.l_opt_icicle.dir': 'West',
    'leads.l_opt_pass_inn.title': 'Steam on the Pass',
    'leads.l_opt_pass_inn.text': 'High on the eastern pass stands an inn\nwreathed in steam. A resting place\nfor travelers.',
    'leads.l_opt_pass_inn.from': 'Traveling merchant in Yule',
    'leads.l_opt_pass_inn.dir': 'East',
    'leads.l_opt_aurora.title': 'The Cliffs of Seven Colors',
    'leads.l_opt_aurora.text': 'Past the frozen lake, on the northern\nfloes, are cliffs where the sky ripples in\nseven colors. The lake ice is thin this year.',
    'leads.l_opt_aurora.from': 'Traveling bard',
    'leads.l_opt_aurora.dir': 'North',
    'leads.l_opt_frost_ship.title': 'The Mast in the Ice',
    'leads.l_opt_frost_ship.text': 'A mast juts from the ice of the floes.\nThe captain of a fleet lost a hundred\nyears sleeps there. -- Dangerous.',
    'leads.l_opt_frost_ship.from': 'Bard at the Pass Inn',
    'leads.l_opt_frost_ship.dir': 'North',
    'leads.l_snow_fox.title': 'Pale Glowing Tracks',
    'leads.l_snow_fox.text': 'Pale glowing animal tracks on the\npass road. The icetail fox is said to\nroam the peak or the ice floes.',
    'leads.l_snow_fox.from': 'The pass road',
    'leads.l_snow_fox.dir': 'North',
    'ev.snow_00_common.LZ.2': ['Mira. The child we kept at your house\nhas taken his first steps.', 'I will not speak to him\nof his mother.', 'So that the storytellers\' songs\ndo not carry him away, too.'],
    'ev.snow_00_common.LZ.3': ['Mira. I have copied your face.\nBecause every morning (no -- there\nare no more mornings), remembering hurts.', 'I will leave the portrait hanging.\nWhat it is a picture of,\nI no longer know.'],
    'ev.snow_00_common.LZ.4': ['Mira. The voice in the book\nhas grown louder of late.\n"You wish to forget, don\'t you?"', 'I do wish to forget. And yet\nI do not want to lose you.\nBoth are true.'],
    'ev.snow_00_common.LZ.5': ['Mira. People who wish to cast off\ntheir names have begun to come\nto the Archive.', 'I did not turn them away.\nI know how heavy\na name can be.'],
    'ev.snow_00_common.LZ.6': ['Mira. Biblia is turning white.\nThe copyists forget\nwhat they have copied.', 'In time, so shall I.\nThat is my mercy.'],
    'ev.snow_00_common.LZ.7': ['Mira. I did not want anyone to wake\nto a morning without their child.', 'That is all\nI did.'],
    'ev.snow_00_common.LZ.8': ['Mira. The book says to me:\ncopy the eight legends, too.', 'Then no one need ever\nlose anything again.', '...Mira. What would you say?\nI can no longer remember\nyour voice.'],
    'ev.snow_00_common.letters.from': '(No sender\'s name)',
    'ev.snow_00_common.letters.title': 'A Letter Never Burned',
    'ev.snow_00_common.lore.title': 'A Letter Never Burned',
    'ev.snow_00_common.lore.text': 'A letter left behind by a Recorder.\nAddressed "To Mira." No sender\'s name.',
    'ev.snow_00_common.lz.say': ['I broke the seal. The ink had bleached\nto white. "To Mira" -- beyond the name,\nnothing can be read.', '(If a little more light returns,\nI might be able to read it.)'],
    'lore.lo_ev_snow.title': 'The Blank Festival Book',
    'lore.lo_ev_snow.text': 'The storybook read at the Bonfire Festival.\nEvery page is white. On the last, faintly:\n"Copy -- Archive Norden Branch."',
    'lore.lo_time_snow.title': 'The Night-Counting Board',
    'lore.lo_time_snow.text': 'A board the firekeepers\' house has\nnotched once for every night.\nOver 7,300 notches. Twenty years\' worth.',
    'lore.lo_war_snow.title': 'The Burned North Gate',
    'lore.lo_war_snow.text': 'The north gate\'s posts are new.\nIt was burned twenty years ago, they say.\nHald can\'t say what he fought.',
    'lore.lo_snow_epitaph.title': 'The Inscription on Dragon Peak',
    'lore.lo_snow_epitaph.text': '"Even if one day morning stops coming,\nmorning is not broken.\nIt has only stopped being turned."',
    'lore.lo_aurora_legend.title': 'Writing on the Cliff',
    'lore.lo_aurora_legend.text': '"Three bearing a crest of light\ncrossed beneath the sky at the world\'s\nnorthern end." -- A tale of another land, long ago.',
    'chronicle.r_snow.title': 'The White Dragon and the Solstice Fire',
    'chronicle.r_snow.parts.0.text': 'On a solstice of endless blizzards,\nthe people of Yule held the Bonfire Festival.',
    'chronicle.r_snow.parts.1.text': 'Before the fire, the apprentice storyteller\ntold "The Dragon and the Maiden\'s Promise."',
    'chronicle.r_snow.parts.2.text': 'Before the fire, the apprentice storyteller\ntold "The Wolf and the Hunter."',
    'chronicle.r_snow.parts.3.text': 'Before the fire, the apprentice storyteller\ntold "The Child Who Stole Fire."',
    'chronicle.r_snow.parts.4.text': 'On the night of the Bonfire Festival,\nthe people of Yule drove off the ice wolves...',
    'chronicle.r_snow.parts.5.text': 'On the festival night, ice wolves surrounded\nthe village. One gate could not be held. What\nwas broken there is written here too.',
    'chronicle.r_snow.parts.6.text': 'Without a fight, the white dragon heard\nthe story, and its frozen heart thawed.',
    'chronicle.r_snow.parts.7.text': 'Crossing blades with the white dragon,\nthe storyteller shattered the ice in its heart.',
    'chronicle.r_snow.parts.8.text': 'The solstice fire was lit upon the summit,\nand auroras rippled across the whole sky.',
    // ---- src/events/snow_festival.js
    'ev.snow_festival.tellTale.caption': 'Learned the old tale "{name}."',
    'ev.snow_festival.tellTale.caption_2': 'You\'ve heard all three old tales.\nWhich one to tell at the festival --\ndecide before the fire.',
    'events.yule_ingrid.say': ['The dragon remembered the story.\n...That\'s what passing a tale on means.', 'Someday, someone will tell\nyour story too.'],
    'events.yule_ingrid.tellTale': ['You need a tale for the festival?\nThen let me tell you the oldest\nstory in this village.', 'A story meant to be told before the fire.\n...Listen well.'],
    'events.yule_ingrid.tellTale_2': ['It isn\'t fire the dragon loves.\nIt\'s the stories.', 'The fire is only the lamp\nthat carries them.'],
    'events.yule_olaf.say': 'The wolves went back to the mountains\nonce the blizzard stopped. ..."Till next time,"\nthey said, I reckon.',
    'events.yule_olaf.tellTale': ['A festival tale? The only one\nI know is the hunter\'s.', '...A tale from my grandfather\'s\ngrandfather\'s time.'],
    'events.yule_olaf.tellTale_2': ['A wolf never forgets a kindness.\nPeople are far more forgetful.', 'If it comes to a siege,\nI\'ll be out there with my bow too.'],
    'events.yule_brenda.say': ['Down south in the Ashen Wastes,\nthey\'ve a story about a child who\nstole fire, too, I hear.', 'A traveler told me.\n...I wonder if it\'s the same child.'],
    'events.yule_brenda.tellTale': ['Oh, a storyteller?\nA festival tale, then. I\'ll tell you\none the children love.', 'The story of the child who stole fire.'],
    'events.yule_brenda.tellTale_2': ['Maybe even the ice walls on the peak\nwould melt for that child\'s fire.', '...That\'s what folk used\nto say, long ago.'],
    'events.yule_fisher.say': ['Ice for the festival lanterns, eh?\nI\'ll lend you my saw.', 'The ice in the middle of the pond is\nthe clearest. Pull in rhythm,\nand it\'ll cut clean.'],
    'events.yule_fisher.say_2': ['Oh, done cutting? Fine ice, that.', 'I\'ll hang the saw back on the hut wall.\n...Good work.'],
    'events.yule_pond_ice.say': 'There\'s enough ice for the lanterns now.',
    'events.yule_pond_ice.say_2': ['A frozen pond. The ice is very thick.', 'With the saw from the fishing hut,\nyou could cut some out.'],
    'events.yule_pond_ice.say_3': 'You set the saw to the ice.\n...Pull, in rhythm.',
    'events.yule_pond_ice.r.title': 'Cutting Ice',
    'events.yule_pond_ice.r.sub': 'Frozen Pond',
    'events.yule_pond_ice.caption': 'You cut out a clean block of clear ice.\n({Math}/3)',
    'events.yule_pond_ice.caption_2': 'The ice cracked.\nTry again.',
    'events.yule_pond_ice.caption_3': 'That\'s all the ice for the lanterns.\nBetter return the saw to Tore.',
    'events.snow_festival.caption': 'The night of the solstice.\nThe whole village gathered\nin Yule\'s square.',
    'events.snow_festival.caption_2': 'A whole year\'s worth of firewood is\nstacked in the great hearth.',
    'events.snow_festival.caption_3': 'The fire is lit.\n-- The solstice fire blazes up\ninto the night sky!',
    'events.snow_festival.caption_4': 'At every tunnel mouth, the ice lanterns\nflickered on at once.\nThe whole village glows blue.',
    'events.snow_festival.say': ['Storyteller.\nTell us this year\'s story,\nhere before the fire.', 'So that it reaches the dragon on the peak.'],
    'events.snow_festival.i.choose.text': 'Which tale will you tell before the fire?',
    'events.snow_festival.say_2': '{hero} stepped up before\nthe blazing fire.',
    'events.snow_festival.caption_5': 'When the tale was done, the square\nfell silent -- and then\nbroke into loud applause.',
    'events.snow_festival.say_3': 'Look! The sparks are drifting\ntoward the peak...\nLike the fire of the child in the story.',
    'events.snow_festival.say_4': 'A fine telling.\n...If the wolves come, this old codger\nwill take up his bow too.',
    'events.snow_festival.say.name': 'Olaf',
    'events.snow_festival.caption_6': 'Just then, the blizzard suddenly worsened.\nThe sparks were scattered\nsideways by the wind.',
    'events.snow_festival.caption_7': 'Howls from deep in the blizzard.\nOne, two...\ntoo many to count.',
    'events.snow_festival.say_5': ['A wolf pack!\nThey\'ve surrounded the village!', 'Shut the gates!\nMen, to the gates!'],
    'events.snow_festival.say_6': ['Three gates. North, east, west.\nWith our hands alone, we can\nonly hold two.', '{hero}, lend us your strength.\nChoose which gate to defend.'],
    'ev.snow_festival.HINT.1': ['The howls... it\'s the north!\nThe loudest voices come from\nthe northern woods.', 'They\'ll hit the other gates too.\n...But the north is the real attack.'],
    'ev.snow_festival.HINT.2': ['The east now. The pack\'s pushing\nin along the eastern pass road.', 'Only small packs to the north and west.'],
    'ev.snow_festival.HINT.3': ['...I hear the pack leader.\nThe great wolf.', 'The leader\'s clever. It\'ll go for\nthe gate we haven\'t been\nseen defending yet.'],
    'ev.snow_festival.PICKS': ['Defend the north gate', 'Defend the east gate', 'Defend the west gate', 'Prepare at the great hearth'],
    'events.snow_siege_wave.say.name': 'Hald',
    'events.snow_siege_wave.i.choose.text': 'Wave {w}. Which gate will you defend?',
    'events.snow_siege_wave.say': 'When you\'re ready, give me\na shout. I\'ll be by\nthe great hearth.',
    'events.snow_siege_wave.say.name_2': 'Jorn',
    'events.snow_siege_wave.caption': 'You ran to {p0}.\nBeyond the blizzard, glowing eyes stand in a row.',
    'events.snow_siege_wave.wins.caption': 'The next pack is coming!',
    'events.snow_siege_wave.say_2': 'Olaf and the village hunters\nloosed their arrows first!\nOne wolf turns tail and runs.',
    'events.snow_siege_wave.caption_2': 'You held {p0}!\nThe villagers somehow managed\nto hold the other gates too.',
    'events.snow_siege_wave.caption_3': 'You held {p0}.\n...But {p1} has been broken!',
    'events.snow_siege_wave.caption.n': 'The stalls before the north gate were\nknocked over, and wolves got into the square.',
    'events.snow_siege_wave.caption.e': 'The east storehouse was ransacked.\nThe smithy\'s wares lie scattered.',
    'events.snow_siege_wave.caption.w': 'The fence of the sled dogs\' kennel\nin the west was smashed.',
    'events.snow_siege_wave.caption_4': 'You warmed yourselves at the great hearth.\n(HP and MP restored.)',
    'events.snow_siege_wave.say_3': 'More are coming.\nGive me a shout when you\'re ready.',
    'events.snow_siege_wave.say_4': 'Next comes the pack leader.\n...The great wolf.\nGive me a shout when you\'re ready.',
    'events.snow_siege_wave.caption_5': 'You read it right!\nFrom out of the blizzard,\nthe great wolf appears!',
    'events.snow_siege_wave.caption_6': 'A howl! The great wolf has broken {p0}!\nIt\'s heading for the great hearth\nin the square!',
    'events.snow_siege_wave.say_5': 'A gigantic wolf with a white coat.\nThe blizzard clings to its body.',
    'events.snow_siege_wave.say_6': 'Through the poorly guarded gate,\nwolf after wolf of the pack\ncomes charging in...!',
    'events.snow_siege_wave.say_7': 'Through the poorly guarded gate,\nwolves come charging in...!',
    'events.snow_siege_wave.caption_7': 'When the great wolf fell, the pack\nscattered into the blizzard.',
    'events.yule_siege_sonja.say': ['I\'ll guard the fire.\nSo... please, the gates.', 'By the great hearth, you can\nwarm yourselves any time.'],
    'events.yule_siege_hald.say': '...It\'s gone quiet.',
    'events.yule_siege_guard.say': 'It\'s not quite like the festival tale,\nbut we\'ll repay a kindness, at least.',
    'events.yule_siege_guard.say_2': 'We\'ll hold the gate\nsomehow.\n...Hurry.',
    'events.snow_dawn.caption': 'The morning bell rang.\nThe sky is still dark. But the\nvillage lamps turn to morning colors.',
    'events.snow_dawn.say': 'On the lookout tower stood a girl\nin a gray cloak, gazing up at the peak.',
    'events.snow_dawn.say_2': 'It isn\'t the dragon\'s body that\'s frozen.\nIt\'s its heart.',
    'events.snow_dawn.say.name': 'Girl in a Gray Cloak',
    'events.snow_dawn.caption_2': 'The girl vanished, as if melting\ninto the blizzard.',
    'events.snow_dawn.say_3': ['{hero}! The fire in the great hearth\nis stronger than it was last night.', 'I\'ve put a spark of the solstice fire\nin a fire pot. Take it to the peak.\nThis fire can melt even the ice wall.'],
    'events.snow_dawn.say_4': ['And one more thing -- the lookout said\nthe ice wall at the peak\'s entrance\nmelted overnight.', '...Maybe the fire of the child\nin the story got there first.'],
    'events.snow_dawn.say.0': 'At {join}, we took a terrible beating.\n...But no one died.',
    'events.snow_dawn.say.0.join': ' and ',
    'events.snow_dawn.say.1': 'I leave the dragon on the peak to you.',
    'events.snow_dawn.read': 'You met the great wolf at {gate}.\nThe pack leader never got through.',
    'events.snow_dawn.miss': 'When the great wolf broke through {gate},\nI thought we were done for.',
    'events.snow_dawn.say.0_read': 'At {join}, we took a terrible beating\nin the waves before.\n...But no one died.',
    'events.snow_dawn.say.name_2': 'Hald',
    'events.snow_dawn.say_5': ['Not one gate was broken.\nI can\'t believe it...', 'The families by the gates you held\nsaid they want to thank you.'],
    'events.yule_siege_resume.caption': 'The village is still surrounded by wolves.\nYou hurry to the great hearth.',
    'events.yule_siege_regroup.caption': 'You wake beside the great hearth\'s fire.\nTalk to the chief to head for the gates again.',
    // ---- src/events/snow_optional.js
    'events.icicle_arrive.caption': 'The Icicle Corridor.\nCountless blue blades of ice\nhang from the ceiling.',
    'events.icicle_2_arrive.caption': 'It\'s dark.\nLight the fire dish, and\nyou should be able to see.',
    'events.icicle_frozen.say': 'Beyond the melted ice,\na treasure chest can be seen.',
    'events.icicle_frozen.say_2': 'A treasure chest is sealed\ninside thick ice.',
    'events.icicle_frozen.say_3': 'As you hold up the solstice fire,\nthe ice melts away before your eyes.',
    'events.icicle_frozen.i.choose': ['Use a fire pot', 'Leave it'],
    'events.icicle_frozen.i.choose.text': 'Melt it with a fire pot?',
    'events.icicle_frozen.say_4': 'You hurl the fire pot.\nFlames lick the ice, melting it away.',
    'events.icicle_frozen.say_5': 'Without fire, there\'s no\nway to melt it.\n(Maybe a fire pot would do?)',
    'events.icicle_guard.say': 'The icicles on the ceiling fell\nof their own accord. ...No --\nthey\'re moving!',
    'events.icicle_guard.say_2': 'The icicle guards shattered\nand scattered across the floor.',
    'events.icicle_seal.say': ['A door with an old crest, carved\nin the shape of a quill.', 'Push or pull, it won\'t open.\n...Does it need some kind of key?'],
    'events.pass_inn_arrive.caption': 'The Pass Inn.\nSteam rises white into the night sky.',
    'events.pass_inn_innkeeper.say': 'Welcome, welcome.\nWelcome to the Pass Inn.\nThe baths and the beds are both warm.',
    'events.pass_inn_shopkeeper.say': 'Anything you need for crossing\nthe pass, you\'ll find here.',
    'events.pass_inn_board.say': ['The inn\'s notice board.', '"Bath inlet frozen. Fire pot wanted.\n-- The Bath Attendant"\n"Pass to the mountain town closed by rockslide."'],
    'events.pass_inn_bath_keeper.say': 'The bath\'s open any time.\nThe pass waters warm you right through.',
    'events.pass_inn_bath_keeper.say_2': ['The bath\'s inlet has frozen solid.\nCan\'t draw any hot water.', 'If only I had a fire pot,\nI could thaw it...'],
    'events.pass_inn_bath_keeper.i.choose': ['Hand over a fire pot', 'Not now'],
    'events.pass_inn_bath_keeper.say_3': ['That\'s a lifesaver! Now the water\'ll flow.', 'A thank-you. A frost charm I kept\nstowed at the back of the bathhouse.'],
    'events.pass_inn_bath_pool.say': 'The bath\'s water inlet.\nIt\'s blocked with ice.',
    'events.pass_inn_bath_pool.say_2': 'You sank into the bath up to your shoulders.\n...It warms you right to the core.',
    'events.pass_inn_scout.say': ['The pass ahead is blocked by a rockslide.\nNo getting through to the mountain town.', 'If Yule\'s solstice fire came back,\nthe snow would ease up, though.'],
    'events.pass_inn_fox_man.say': ['I\'m after icetail fox pelts,\nbut they\'re hard to come by.', 'Their dens are at the Aurora Cliffs\non the northern ice floes, I hear.\nPast the frozen lake.'],
    'events.pass_inn_rumor_gossip.say': ['In Fern, the forest village to the west,\nthree woodcutters never came home, I hear.', '...Though I also heard\nthey\'ve been found.'],
    'events.pass_inn_rumor_gossip.say_2': 'In the marsh town to the east, children\nvanish in the fog, they say.\nHow frightening.',
    'events.pass_inn_rumor_bard.say': ['Have you seen the mast sticking up\nout of the ice on the floes?', 'The captain of a fleet lost a hundred years\nis still searching for port, they say.\n...Best not go near.'],
    'events.pass_inn_rumor_bard.say_2': 'Down south in the Ashen Wastes,\nthe firebird\'s egg is growing cold, I hear.',
    'events.pass_inn_rumor_merchant.say': ['In Dovan, the mining town past the pass,\nan iron guardian came out of the\ndepths of the mine, they say.', 'If not for the rockslide,\nI could haul my goods there.'],
    'events.pass_inn_rumor_merchant.say_2': 'In Kasim, down in the southern desert,\nthey\'re looking for caravan guards, I hear.',
    'events.aurora_arrive.caption': 'The northern ice floes, the Aurora Cliffs.\nThe frozen sea stretches on forever.',
    'events.aurora_view.caption': 'Auroras ripple across the whole sky.\nGreen, pale pink, and blue.\nThe solstice fire burns upon the peak.',
    'events.aurora_view.caption_2': 'Through a gap in the blizzard,\nfor just a moment, the sky\nrippled in seven colors.',
    'events.aurora_view.caption_3': 'Near the cliffs, you thought you heard\nthe wingbeats of a shining bird.',
    'events.aurora_legend.say': ['Old writing is carved into\nthe stone of the cliff.', '"Three bearing a crest of light\ncrossed beneath the sky at the\nworld\'s northern end."', '...It seems to be a tale from\nanother land, long, long ago.'],
    'events.frost_ship_arrive.caption': 'A sailing ship locked in ice.\nOn deck, the frozen shadows\nof sailors stand in rows.',
    'events.frost_ship_arrive.caption_2': '-- Something strong lurks here.\nThere\'s no shame in turning back.',
    'events.frost_ship_log.say': ['A frozen ship\'s log.', '"Homeward to the northern port. By the solstice.\n...The ice is coming. Lower the sails."', 'The date is a hundred years ago.'],
    'events.frost_ship_chart.say.0': 'A sea chart on the captain\'s table.\nA port at the far north is circled.',
    'events.frost_ship_chart.say.1': 'On the chart, the outline of\nthe frostbound compass remains.',
    'events.frost_ship_chart.say.1_2': 'The compass\'s resting place is empty.',
    'events.frost_ship_boss.say': ['The ice in the captain\'s cabin creaked.', 'A captain cloaked in frost\nslowly rises to his feet.'],
    'events.frost_ship_boss.say_2': ['...Is the port not yet in sight?\nWe must return... by the solstice...', 'Stand aside.\nThis ship belongs to no one else!'],
    'events.frost_ship_boss.say.name': 'Frozen Fleet Captain',
    'events.frost_ship_boss.i.choose': ['Fight', 'Turn back'],
    'events.frost_ship_boss.i.choose.text': '-- A powerful foe. Fight?',
    'events.frost_ship_boss.say_3': '{hero} and the others quietly\nbacked away from the captain\'s cabin.',
    'events.frost_ship_boss.say_4': ['The ice fell away from the\ncaptain\'s body.', '"...Ah. I can see\nthe harbor lights..."', 'The man faded away,\nas if melting into the light.'],
    // ---- src/events/snow_peak.js
    'ev.snow_peak.NEVE.name': 'Neve the White Dragon',
    'ev.snow_peak.GIANT.name': 'Ice Wall Giant',
    'events.peak_arrive.caption': 'White Dragon Peak.\nThe blizzard lashes in sideways.',
    'events.peak_arrive.caption_2': '...Ahead, thick ice seems to\nblock the path.\nIt may take the fire of\nYule\'s Bonfire Festival.',
    'events.peak_icewall.say': 'Water from the melted ice\nis freezing again underfoot.',
    'events.peak_icewall.say_2': ['A thick wall of ice blocks the path.\nStriking it does nothing at all.', 'Ordinary fire won\'t melt it.\n...It would take a fire as strong\nas the solstice fire.', '...The fire of Yule\'s Bonfire Festival,\nperhaps.'],
    'events.peak_icewall.say_3': 'You hold the spark of the solstice fire\nup to the wall of ice.',
    'events.peak_icewall.caption': 'The ice wall melts away with a roar...!',
    'events.peak_overlook.say.0': 'From the ledge, the snowfields spread\nout below. Yule\'s solstice fire\nlooks like a small red dot.',
    'events.peak_overlook.say': ['From the ledge, you look down over\nthe snowfields in the blizzard.', 'Far below, the fire in Yule\'s\ngreat hearth is faintly visible.'],
    'events.peak_giant.say': 'Thud... thud...\nThe wall of ice itself stood up.',
    'events.peak_giant.say_2': '...None shall pass...\nbeyond this point...',
    'events.peak_giant.say_3': ['The giant\'s body cracked and crumbled.\nShards of ice scatter in the blizzard.', 'Behind it, stone steps leading\nto the summit appeared.'],
    'events.peak_top_arrive.caption': 'The summit of White Dragon Peak.\nOn the windswept rocks,\nthe blizzard swirls.',
    'events.peak_epitaph.say': ['Old writing is carved into a great rock.\nDeep letters, as if cut by claws.', '"Even if one day morning stops coming,\nmorning is not broken.\nIt has only stopped being turned."'],
    'events.peak_altar.say': ['The solstice fire burns on the ice altar.\nThe blizzard blows no more.', 'Neve\'s presence fills\nthe whole peak.'],
    'events.peak_altar.say_2': 'An altar of ice.\nThe stand for the fire is empty.',
    'events.peak_neve.caption': 'Tearing through the blizzard, a white dragon\ndescended upon the altar.',
    'events.peak_neve.say': '...Begone... child of man...\nOn this peak, there are\nno more stories to tell...!',
    'events.peak_neve.i.choose': ['Tell a story', 'Fight'],
    'events.peak_neve.i.choose.text': 'Neve spreads its wings.',
    'events.peak_neve.say_2': 'The dragon\'s eyes are cold, as if\nfrozen solid. ...Words won\'t reach it.',
    'events.peak_neve.say_3': ['{hero} raised the solstice fire and\ntold the festival tale once more.', 'The tale of the dragon\'s promise\nwith the maiden who carried fire.'],
    'events.peak_neve.caption_2': 'Deep within Neve\'s eyes,\nsomething slowly begins to thaw.',
    'events.peak_neve.say_4': 'The white dragon folded its legs,\nand the blizzard suddenly weakened.',
    'events.peak_neve.say_5': '...Warm. So the children of man\nhad not forgotten me after all.',
    'events.peak_neve.say_6': 'I shall calm the blizzards.\nStoryteller, you have my thanks.',
    'events.snow_finale.say': '...Take this with you.\nOne of my scales.',
    'events.snow_finale.say_2': 'A dragon fang, broken in the battle,\nlay on the snow.',
    'events.snow_finale.say_3': '{hero} set the solstice fire\nupon the altar of ice.',
    'events.snow_finale.caption': 'The blizzard stopped.',
    'events.snow_finale.caption_2': 'The clouds parted, and auroras\nrippled across the whole sky.\nGreen, pale pink, and blue.',
    'events.snow_finale.caption_3': 'For just a moment, the horizon\nseemed to grow a little paler.',
    'events.snow_finale.caption_4': 'Yule.\nIn the square, the blizzard gone,\nthe whole village gazed up at the sky.',
    'events.snow_finale.say_4': ['{hero}! Welcome back.', 'I went to cut tonight\'s notch\ninto the night-counting board.\n...But my hand stopped.', '...Tonight, the sky is brighter\nthan usual.'],
    'events.snow_finale.say_5': ['We carry the fire to the peak at the\nsolstice, so that one day the sun returns.', '...That\'s what my grandfather\nused to say.'],
    'events.snow_finale.say.name': 'Village Elder',
    'events.snow_finale.say_6': '{hero} opened the Chronicle.\nHow should this village be written?',
    'events.snow_finale.i.choose.0': 'Write only of the victory',
    'events.snow_finale.i.choose.1': 'Also write of the gate that fell',
    'events.snow_finale.i.choose.1_2': 'Also write of the night the village shook',
    'events.snow_finale.i.choose.text': 'What will you write in the Chronicle?',
    'events.snow_finale.say_7': '"...There was a gate that could not be held.\nWhat was broken there\nis written here too."',
    'events.snow_finale.say_8': '"On the night of the Bonfire Festival,\nthe people of Yule drove off the ice wolves..."',
    'events.snow_day2.caption': 'The second day of the delayed festival.\nStalls line the square, and\nchildren run about in the snow.',
    'events.snow_day2.say.0': '...Before the festival, one thing.',
    'events.snow_day2.say.1': 'By {join}, there are those\nwhose homes were wrecked.\nLet me read out their names.',
    'events.snow_day2.say.1.join': ' and ',
    'events.snow_day2.caption_2': 'Beside the broken gate, Jorn read out\nthe families\' names, one by one.\nThe square was quiet for a while.',
    'events.snow_day2.say': ['{hero}, I set aside some\nof the solstice fire.', 'Three lanterns on the Lampkeepers\'\nRoad, past the east gate, are still out.\nUse this to light them.'],
    'events.snow_day2.caption_3': 'Before the houses by the gates you held,\nboxes of thanks have been left.',
    // ---- src/events/snow_quests.js
    'ev.snow_quests.FISH.0.label': 'Tier One (Minnow)',
    'ev.snow_quests.FISH.1.label': 'Tier Two (Silverfish)',
    'ev.snow_quests.FISH.2.label': 'Tier Three (Lord of the Ice)',
    'events.snow_fishing_talk.say': ['During the festival, it\'s the ice fishing\ncontest. Drop your line through the\nhole inside the hut.', 'When a fish bites, pull it up\nin rhythm. There are\nthree tiers.'],
    'events.snow_fishing_talk.say_2': 'The lantern ice is in the middle of the pond.\nJust return the saw when\nyou\'re done cutting.',
    'events.snow_fishing_talk.say_3': 'Far as I know, you\'re only the second\never to land the Lord of the Ice.',
    'events.snow_fishing_talk.say_4': 'If you\'re fishing, it\'s the hole at the back.',
    'events.yule_fish_hole.say': 'A fishing hole cut in the ice.\nBetter ask the old man\nin the fishing hut.',
    'events.yule_fish_hole.labels': '(Done)',
    'events.yule_fish_hole.i.choose.0': 'Not now',
    'events.yule_fish_hole.i.choose.text': 'Which tier will you fish?',
    'events.yule_fish_hole.say_2': 'Finish the tier before\nthat one first.',
    'events.yule_fish_hole.say.name': 'Tore',
    'events.yule_fish_hole.r.title': 'Ice Fishing: {label}',
    'events.yule_fish_hole.r.sub': 'Fishing Hut',
    'events.yule_fish_hole.say_3': 'Got away, did it?\nFish under the ice are impatient.',
    'events.yule_fish_hole.caption': 'A splendid catch!',
    'events.yule_fish_hole.say_4': 'Why, this is... the Lord of the Ice!\nHere, take this -- proof you\'re a master.',
    'events.yule_fish_hole.say_5': 'Good hands. Here, your prize.',
    'events.yule_sled.say': ['Blanca! Where did you\nrun off to!', '...You brought her back?\nThank you, traveler.'],
    'events.yule_sled.say_2': ['To thank you, I\'ll bring out the sled.\nWith Blanca leading, it\'ll glide\neven over thin ice.', 'Across the frozen lake to the\nnorthern ice floes, whenever you like.'],
    'events.yule_sled.i.choose': ['Cross to the northern ice floes', 'Not now'],
    'events.yule_sled.i.choose.text': 'Want to ride the sled?',
    'events.yule_sled.caption': 'The dogs barked, and the sled took off\nacross the frozen lake like the wind.',
    'events.yule_sled.say_3': ['I\'m Nils.\nI look after the sled dogs.', 'My lead dog, Blanca, bolted on the night\nof the blizzard. Ran off toward the snowy\nwoods and never came back.'],
    'events.yule_sled.say.0': 'Without her, the sled can\'t run.\nIf you find her, would you\nbring her home?',
    'events.yule_sled.say_4': 'I think Blanca\'s deep in the snowy woods.\nSomewhere around the hollow\nto the northeast.',
    'events.yule_dog.say': 'Woof!\n(She\'s wagging her tail hard.)',
    'events.yule_dog.say.name': 'Blanca',
    'events.snow_woods_dog.say': ['A sled dog lay curled up\nin a snowy hollow.', 'The name "Blanca" is\nburned into its collar.'],
    'events.snow_woods_dog.say_2': 'Must be someone\'s dog.\n...Better ask around in Yule.',
    'events.snow_woods_dog.say_3': 'Woof!\n(She seems ready to follow you.)',
    'events.snow_woods_dog.say.name': 'Blanca',
    'events.snow_woods_dog.caption': 'Blanca is following you.\nTake her home to Nils in Yule.',
    'events.world_snow_floe_sled.say': 'A road of thick ice has formed on the\nfrozen lake. Looks like you could walk back.',
    'events.world_snow_floe_sled.i.choose': ['Return to Yule', 'Not now'],
    'events.world_snow_floe_sled.i.choose.text': 'Blanca\'s sled is waiting.',
    'ev.snow_quests.MATS.snow_mat_ice': 'a shard of clear ice',
    'ev.snow_quests.MATS.snow_mat_coal': 'charcoal from the great hearth',
    'ev.snow_quests.MATS.snow_mat_berry': 'red berries from the snowy woods',
    'events.yule_sculptor.say': 'The village kids love that statue!\nThank you.',
    'events.yule_sculptor.say_2': ['I\'m Liisa. I\'m making the snow statue\nfor the festival. ...But I don\'t have\nenough things to decorate it.', 'A shard of clear ice,\ncharcoal from the great hearth,\nand red berries from the snowy woods.'],
    'events.yule_sculptor.say_3': 'Once you\'ve got all three, I\'ll make it\nany shape you like!',
    'events.yule_sculptor.say.0': '{p0} more to go!',
    'events.yule_sculptor.say.1': '{list}.',
    'events.yule_sculptor.say.1.join': ', ',
    'events.yule_sculptor.i.choose': ['A dragon', 'The wolf and the hunter', 'The great hearth'],
    'events.yule_sculptor.i.choose.text': 'What kind of statue shall it be?',
    'events.yule_sculptor.caption': 'Liisa and the children packed the snow,\ncarved it, and decorated it...',
    'events.yule_sculptor.say_4': 'Done!\nHere, this is for you, as thanks.',
    'events.snow_mat.say': 'You\'ve picked up plenty already.',
    'events.snow_mat.caption': 'You picked up {p0}.',
    'events.yule_base_kid.say': ['This is our secret base!\nIf you want in, say the password!', 'What does the dragon\nlike best of all?'],
    'events.yule_base_kid.i.choose': ['Fire', 'Ice', 'Stories', 'I don\'t know'],
    'events.yule_base_kid.say_2': 'Correct!\nYou can come in!',
    'events.yule_base_kid.say_3': 'Go ask the village kids!',
    'events.yule_base_kid.say_4': 'Bzzt! Wrong!\nThe fire\'s just a bonus, they say.',
    'events.snow_waylamp.say': 'The solstice fire burns in the\nroadside lantern. The blizzard\naround it has softened.',
    'events.snow_waylamp.say_2': ['The roadside lantern\'s flame\nhas gone out.', 'The tallow has frozen. Ordinary\nfire won\'t light it, it seems.'],
    'events.snow_waylamp.say_3': 'You passed a share of the\nsolstice fire to the lantern.',
    'events.snow_waylamp.caption': 'The lantern is lit!\nMonsters shouldn\'t come near\nthis spot anymore.',
    'events.snow_waylamp.caption_2': 'All the lanterns on the Lampkeepers\'\nRoad are lit.',
    'events.snow_woods_arrive.caption': 'The snowy woods.\nTrees felled by the blizzard\nlie everywhere.',
    'events.snow_woods_camp.say': ['Gathering firewood? For Yule\'s festival?\nI\'m hauling some myself.', 'Here, something to fill your belly.'],
    'events.snow_woods_camp.say_2': ['The yeti in the northern clearing\nis big, but weak to fire.', 'Between the rocks to the northwest, once you\nslide down the slope you can\'t climb back.\nGrab the chest, then leave by the west path.'],
    'events.snow_woods_yeti.say': 'Behind a fallen tree, a mound of white fur\nmoved. ...A yeti!',
    'events.snow_woods_yeti.say_2': 'The yeti fled deeper into the woods.',
    'events.snow_woods_log.say': 'The stump of a fallen tree.\nThe firewood\'s already been taken.',
    'events.snow_woods_log.say_2': ['A well-dried fallen tree.', '{hero} cut the fallen tree into\npieces small enough to carry.'],
    'events.snow_woods_log.caption': 'Gathered firewood for the festival. ({k}/3)',
    'events.snow_woods_log.caption_2': 'That\'s three loads of firewood.\nBetter tell Jorn, the chief of Yule.',
    'events.snow_pass_cairn.say': ['An old waymarker cairn of flat,\nstacked stones.', 'On the wooden post at its top,\nfrozen scraps of cloth are tied.', 'Travelers who crossed the pass must\nhave tied them, praying for safe passage.'],
    'events.snow_pass_hut.say': ['A stone lookout hut with a caved-in roof.', 'Inside its walls, the wind eases a little.\nOn blizzard nights, travelers must\nhuddle here.'],
    'events.snow_foot_bones.say': ['A dragon\'s ribs, jutting from the snow.', 'Now that the blizzard has stopped,\nthe white of the bones seems to\nmelt into the color of the sky.'],
    'events.snow_foot_bones.say_2': ['Bones so tall you have to look up,\njutting from the snow. A dragon\'s ribs.', 'The people of Yule say they belong to a\nwhite dragon that fell asleep long ago.'],
    'events.snow_foot_shrine.say': ['The solstice fire burns in\na stone fire dish.', 'The flame is small, and yet,\nstrangely, the wind doesn\'t put it out.'],
    'events.snow_foot_shrine.say_2': ['In the middle of a ring of standing stones,\na stone fire dish packed with snow.', 'Before carrying the solstice fire to\nthe peak, it was lit here once, they say.'],
    'events.snow_road_hut.say': ['A round hunting hut ringed by a stake fence.', 'The door is frozen shut and won\'t budge.\nIt must be used only in hunting season.'],
    'events.snow_pass_springs.say': ['Hot water wells up between the rocks.\nWhite steam has melted the snow around it.', 'The Pass Inn\'s baths must be\npiped from here.'],
    'events.world_snow_lake.say': ['A road of thick ice runs straight north\nacross the frozen lake.', 'Beyond lie the northern ice floes.'],
    'events.world_snow_lake.say_2': ['A frozen lake. The ice is thin this year,\nand black water shows here and there.', 'A dog sled might be able to\nglide across.'],
    'events.world_snow_fox.say': ['Small animal tracks in the snow,\nglowing a faint, pale blue.', 'The tracks seem to lead\noff to the north.'],
    'events.world_snow_trapper.say': ['The ice cave in the western cliffs --\nthe Icicle Corridor, they call it.', 'In the dark at the back are icicle guards.\nLight the fire dishes before\nyou go near.'],
    'events.world_snow_pilgrim.say': ['Since the blizzard stopped,\nthe pass has gotten much easier.', 'Stop for a soak at the Pass Inn\non your way.'],
    'events.world_snow_pilgrim.say_2': ['I meant to cross to the mountain town,\nbut there\'s a rockslide past the pass.', 'I\'ll wait at the Pass Inn\nfor the snow to stop.'],
    'events.world_snow_scout.say': 'I saw the dragon from the peak\nflying across the sky!\n...That wasn\'t a dream, right?',
    'events.world_snow_scout.say_2': ['The dragon on the peak takes a big\nbreath before it breathes the blizzard.', 'When you see it breathe in,\neveryone brace yourselves.\n...That\'s what Grandpa said.'],
    // ---- src/events/snow_yule.js
    'events.yule_arrival.caption': 'Between deep snowdrifts,\npaths of packed snow\nwind and connect.',
    'events.yule_arrival.caption_2': 'Embracing the square lay\nlonghouses, long as\na dragon\'s back.',
    'events.yule_arrival.caption_3': 'At every tunnel mouth,\nice lanterns stood in rows.\n-- The festival preparations are under way.',
    'events.yule_arrival.caption_4': 'The fire in the square\'s great hearth\nburned terribly thin.',
    'events.yule_board.say': ['A new notice on the board:\n"The Bonfire Festival will hold a second day.\n-- Chief Jorn"', 'Below it, one in a child\'s hand:\n"Snowball fight! Players wanted."'],
    'events.yule_board.say_2': ['A festival notice is on the board.', '"The Solstice Bonfire Festival. Help wanted:\nfirewood, ice lanterns, a storyteller.\n-- Chief Jorn"'],
    'events.yule_board.say_3': ['Below it, several small notices\nare pinned on top of one another.', '"Ice fishing contest. During the festival."\n"Sled dog missing. -- Nils"\n"Wanted: snow statue decorations. -- Liisa"'],
    'events.yule_jorn.say': ['By the broken gate, I read out\nthe families\' names. ...Thank you\nfor writing it down.', 'There are things we may forget,\nand things we must not.'],
    'events.yule_jorn.say_2': ['The second day\'s festival is lively.\n{hero}, it\'s all thanks to you.', 'This year\'s story must have reached\nthe dragon on the peak, too.'],
    'events.yule_jorn.say_3': ['The siege is over. ...But the\nblizzard still hasn\'t stopped.', 'Carry the solstice fire to the\ndragon on the peak. I beg you.'],
    'events.yule_jorn.say_4': ['Good light to you, traveler.\nI\'m Jorn, chief of Yule.', 'Tonight\'s the solstice, the festival night.\nWe burn the solstice fire in the great hearth,\ntell an old tale, and carry both to the peak.'],
    'events.yule_jorn.say_5': ['We bring fire and a story to the white\ndragon on the peak, and the dragon calms\nthe blizzards. ...That\'s our promise.', 'But this year, since autumn, the blizzard\nhasn\'t let up for a single day.\nOur stories aren\'t reaching the dragon.'],
    'events.yule_jorn.say_6': ['We\'re short of hands for the preparations.\nCould I ask you? Three jobs.', 'Three loads of firewood from the snowy woods.\nIce for the lanterns from the frozen pond.\nAnd an old tale to tell at the festival.'],
    'events.yule_jorn.say_7': ['The village elders know the old tales.\nIngrid at the meeting hall, Olaf\nthe hunter, and old Granny Brenda.', 'If we had the festival book, we\'d only\nneed to read from it... Try asking Sonja.'],
    'events.yule_jorn.i.choose': ['Start the festival', 'Keep preparing'],
    'events.yule_jorn.i.choose.text': 'The ice lanterns aren\'t done. Start anyway?',
    'events.yule_jorn.say_8': 'Borrow a saw from Tore,\nat the fishing hut on\nthe frozen pond.',
    'events.yule_jorn.i.choose_2': ['Start the festival', 'Wait a little longer'],
    'events.yule_jorn.i.choose.text_2': 'Everything\'s ready. Start the festival?',
    'events.yule_jorn.say_9': 'When you\'re ready,\ngive me a shout anytime.',
    'events.yule_jorn.confirm': ['Start the festival\tCan\'t leave until dawn', 'Keep preparing'],
    'events.yule_jorn.confirm.text': ['Once the festival starts, the gates\nstay shut until dawn. After that,\nthere\'s no leaving the village.', 'Are your potions and gear ready?'],
    'events.yule_jorn': 'Firewood from the snowy woods ({var}/3)',
    'events.yule_jorn_2': 'Ice from the frozen pond',
    'events.yule_jorn_3': 'Old tales ({length}/3)',
    'events.yule_jorn.say.0': 'Still left to prepare:\n{join}.',
    'events.yule_jorn.say.0.join': ', ',
    'events.yule_jorn.say.1': 'Nearly there.\nI\'d like the fire lit before tonight\'s out.',
    'events.yule_jorn.say.1_2': 'The snowy woods are out the east gate\nand down to the south.',
    'events.snow_jorn_reward.say': ['{hero}, Yule\'s thanks.\nA solstice fire charm, handed\ndown in our village.', 'They say the maiden who carried the fire\nbrought it back from the peak.'],
    'events.snow_jorn_reward.say_2': 'On cold nights, hold it to your chest.\n...It\'s warm.',
    'events.yule_sonja.say': ['I didn\'t cut a notch into\nthe night-counting board tonight.', '...Because the sky was brighter\nthan usual.'],
    'events.yule_sonja.say_2': ['The solstice fire is burning on the peak.\nYou can see it even from here.', 'My grandmother told me, "Keep counting\nuntil morning comes."\nI wonder what morning is.'],
    'events.yule_sonja.say_3': ['Don\'t lose that spark of the solstice fire.', 'Even the ice wall on the peak\nshould melt for this fire.'],
    'events.yule_sonja.say_4': ['...The fire\'s so thin.\nI add tallow and add tallow, but...', 'I\'m Sonja.\nDaughter of the firekeepers\' house.\nI tend the fire in the great hearth.'],
    'events.yule_sonja.say_5': ['At the festival, we read from the\nstorybook in front of the fire.\nThe same book, every year.', 'But this year, when I opened it...\nit was blank. Not a single\nletter was left.'],
    'events.yule_sonja.say_6': 'The book\'s on the lectern in the meeting\nhall. Take a look. ...Maybe you\'ll\nfind something.',
    'events.yule_sonja.say_7': ['"Copy -- Archive Norden Branch"...?\nLast autumn, people in white came\nand borrowed the book.', 'When it came back, it was blank.\nThey stayed in the empty house\non the edge of the village.'],
    'events.yule_sonja.say_8': 'The book\'s on the lectern in the hall.\nThe hall with the great hearth.',
    'events.yule_hald.say': ['The blizzard\'s stopped.\n...How many years since the peak\nlooked this clear?', 'The story of my fingers?\n...Never mind that now.'],
    'events.yule_hald.say_2': ['Well defended.\n...If you\'re going to the peak, it\'s straight\nout the north gate.', 'There\'s a giant.\nTake fire with you.'],
    'events.yule_hald.say_3': ['...Do you hear it?\nThe howling, deep in the blizzard.', 'Closer every night.\nThe wolves are led by\na pack leader.'],
    'events.yule_hald.say_4': ['When the festival fire blazes up,\nthe village grows bright.\n...Wolves don\'t mind the light.', 'Three gates. North, east, west.\nWe\'d best think how to guard them.'],
    'events.yule_hald.tips.0': ['The pack pushes in from whichever\ndirection the howling\'s loudest.', 'Learn to tell where\nthe howls come from.'],
    'events.yule_hald.tips.1': ['The leader\'s clever. It goes for the\nweakest gate. ...The one you\'ve\nnever once guarded.', 'It\'s a game of reading each other.'],
    'events.yule_hald.tips.2': ['...These fingers?\nThe night the north gate burned.', 'What I fought, even I\ncan\'t say. The gate was rebuilt\nafter that.'],
    'events.yule_burnt_gate.say.0': 'The north gate\'s posts are newer than the rest.\nOnly the stones at their base are scorched black.',
    'events.yule_burnt_gate.say': 'You remember the sewn-shut fingers\nof Hald\'s gloves.',
    'events.yule_watch_e.say': 'Even the lookouts have nothing to do\ntonight but count stars.',
    'events.yule_watch_e.say.0': ['The great wolf that leads the pack wraps\nitself in the blizzard after it howls,\nthen leaps at you, they say.', 'When you hear the howl, everyone brace\nyourselves. ...My father\'s words.'],
    'events.yule_watch_e.say.1': ['When the giant on the peak glows white, it\nputs on armor of ice. Blades won\'t get through.', 'Show it fire, and it can\'t form the armor.\nEven if it does, fire breaks it, they say.'],
    'events.yule_soup.say': ['You must be frozen.\nSoup simmered over a tallow fire.\n...It\'ll warm you.', 'I\'ll pour some into a bottle\nfor you to take on your travels.'],
    'events.yule_soup.say_2': 'Thanks to the solstice fire, we can share\nour tallow again. The soup\'s\nricher now, too.',
    'events.yule_soup.say_3': 'The tallow\'s all rationed out and\ngathered at the great hearth.\n...The fire\'s so thin this year.',
    'events.yule_traveler.say': ['Up on the eastern pass there\'s an inn\nwreathed in steam. The Pass Inn.', 'The road to the mountain town\'s blocked\nby a rockslide, but you can reach the inn.'],
    'events.yule_tadeo.say.0': 'Oil\'s stopped selling.\n...That\'s a good thing, probably.',
    'events.yule_tadeo.say.0_2': 'Lamp scrip? I\'ll take it, but paper\'s\nworth has been shaky lately.',
    'events.yule_tadeo.say': ['Good light to you. Tadeo, of the\nLampkeepers\' Guild. Lamps here burn\ntallow. It\'s all rationed.', 'Oil\'s pricey because\nthe Great Beacons have dimmed.'],
    'events.yule_woodsman.say': 'Thanks for hauling those logs.\nThis year\'s firewood\nburns well.',
    'events.yule_woodsman.say_2': ['For firewood, the fallen trees in the snowy\nwoods are best. Out the east gate, then\nsouth down the pass road.', 'There\'s one fallen tree in each of three\nclearings. The one in the north clearing\'s\nwhere a yeti makes its den.'],
    'events.yule_woodsman.say_3': 'There\'s talk of a crate some peddler\ndropped past the stream on\nthe woods\' east side.',
    'events.yule_oldman.say.0': 'The solstice fire\'s burning on the peak.\nSame color as when I\nwas a boy.',
    'events.yule_oldman.say': ['Since my grandfather\'s day,\nit\'s always been night.', '...No, until the war, it was\na little more...\nNow, what war was that?'],
    'events.yule_oldman.say_2': ['The western hollow on the plateau at the\npeak\'s entrance. When I was young, I went\nthrough the snow wall there.', 'Behind it was a hunter\'s hidden store.\n...Wonder if it\'s still there.'],
    'events.yule_scribe.say': ['By decree of the Archive, this village\'s\nlegends are to be copied for\ntheir protection.', '...Don\'t worry. What we copy will be\nkept with great care in the Great Archive.'],
    'events.yule_kid_a.say': 'You got into Pekka\'s base?\nNo fair.',
    'events.yule_kid_a.say_2': ['You wanna get into Pekka\'s\nsecret base? You need the password.', 'The password is what the dragon likes\nbest of all. ...The rest is\na secret!'],
    'events.yule_kid_b.say': 'Let\'s have a snowball fight\nin the statue garden!',
    'events.yule_kid_b.say_2': ['What the dragon likes best?\nIt\'s not fire.\nFire\'s just a bonus, they say.', 'That\'s what Granny Ingrid\nsaid!'],
    'events.yule_hearth.say': ['The solstice fire burns high\nin the great hearth.', 'The sparks are drawn up\ntoward the peak.'],
    'events.yule_hearth.say_2': 'The fire in the great hearth outlasted\nthe night of the siege and\nis still burning.',
    'events.yule_hearth.say_3': ['The great hearth in the square.\nA tallow fire flickers thinly.', 'The figures of a dragon and a maiden\nare carved into its stone rim.'],
    'events.yule_pond.say': ['A frozen pond. Several fishing holes\nhave been cut in the ice.', 'The fishing hut sits on sled runners\nout on the ice.'],
    'events.yule_north_gate.say': 'Beyond the north gate, White Dragon\nPeak stands out clearly.',
    'events.yule_north_gate.say_2': ['The north gate. The road beyond\nleads to White Dragon Peak.', 'Past the blizzard, the peak\'s shadow\nis faintly visible.'],
    'events.yule_night_door.say': ['The door is firmly barred from inside.', '...Someone inside is soothing a child.\nTonight, the gates must be held.'],
    'events.yule_snowman.say.dragon': 'A dragon statue of snow and ice.\nIts wings gleam in the moonlight.',
    'events.yule_snowman.say.wolf': 'A statue of the wolf and the hunter\nin snow. Stones are set as the wolf\'s eyes.',
    'events.yule_snowman.say.hearth': 'A snow statue of the great hearth.\nA light is burning inside it.',
    'events.yule_hall_hearth.say': 'In the meeting hall\'s hearth burns\nfire shared from the peak.',
    'events.yule_hall_hearth.say.0': 'The meeting hall\'s hearth.\nOn the festival night, fire is carried\nfrom here to the square, they say.',
    'events.yule_nightboard.say.0': 'A long board hangs on the wall,\ncovered edge to edge in\nsmall notches.',
    'events.yule_nightboard.say': ['The firekeepers\' house seems to have\ncut one notch for every night.', '...Counting them,\nthere are over 7,300.\nTwenty years\' worth.'],
    'events.yule_nightboard.say_2': 'Beside the newest notch,\nthe board is still bare.',
    'events.yule_blank_book.say': ['A leather-bound book on the lectern.\nThe storybook of the Bonfire Festival.', 'You turn the pages.\n...White. Every page is\ncompletely white.'],
    'events.yule_blank_book.say_2': ['On the last page, faint letters\nremain.', '"Copy -- Archive Norden Branch"'],
    'events.yule_hall_helper.say': 'Food for the festival\'s second day.\nHave some yourself!',
    'events.yule_hall_helper.say_2': ['The fur peddler in the square only\nsets up shop during the festival.', 'If you\'re going to the peak,\nthick furs will help.'],
    'events.yule_hall_kid.say': ['Why is the morning bell\ncalled the "morning" bell?', '...Nobody knows, they said.'],
    'events.yule_inn_keeper.say': 'Welcome!\nWe\'re full up with guests for\nthe festival\'s second day!',
    'events.yule_inn_keeper.say_2': 'Welcome!\nWelcome to the Snowlight Inn.\nOn blizzard nights, do stay.',
    'events.yule_inn_guest.say': ['There\'s an ice cave in the western cliffs.\nThe Icicle Corridor, they call it.', 'Deep inside, I saw a treasure chest\nsealed in the ice.\n...No getting it without fire.'],
    'events.yule_inn_bard.say': ['Past the frozen lake, on the northern floes,\nare cliffs where the sky ripples\nin seven colors.', 'The lake ice is thin this year, so you\ncan\'t cross. A dog sled might glide\nover thin ice, though.'],
    'events.yule_inn_desk.i.choose': ['Write a letter to Pim', 'Not now'],
    'events.yule_inn_desk.i.choose.text': 'There\'s paper and a quill on the desk.',
    'events.yule_inn_desk.say': ['{hero} wrote about the Bonfire Festival\nin the snow village and the white\ndragon on the peak.', 'The landlady put the letter\non the mail sled.'],
    'events.yule_inn_desk.say_2': 'The inn\'s desk. Paper and a quill\nlie on it.',
    'events.yule_item_keeper.say': 'If you\'re going to the peak, take some\nfire pots. ...Welcome.',
    'events.yule_smith.say': ['On the night of the siege, they ransacked\nthe east storehouse. Not many good\nwares left.', '...Still, have a look.'],
    'events.yule_smith.say_2': 'Welcome. The snowfield smithy.\nFur-lined gear stands up to the cold.',
    'events.yule_smith.line': 'It\'s only what\'s left, but have a look',
    'events.yule_fur.say': 'This shop\'s open only during the festival.\nYeti fur is warm, you know.',
    'events.yule_jorn_ledger.say': ['The chief\'s ledger. Each household\'s\nshare of tallow, written in\nfine detail.', '"This year, until the solstice,\nevery household burns half its lamps."'],
    'events.yule_jorn_wife.say': ['I\'m sorry my husband asks so much of you.\n...Here, take this.', 'A thawing draught, for when you\'re frozen.'],
    'events.yule_jorn_wife.say_2': 'That man\'s overdoing it with\nthe second day\'s festival.',
    'events.yule_jorn_wife.say_3': 'With the festival preparations,\nhe hasn\'t slept a wink.',
    'events.yule_sonja_fire.say.0': 'The hearth of the firekeepers\' house.\nIts fire was taken from the same seed\nas the festival fire, they say.',
    'events.yule_sonja_note.say': ['A single old sheet of paper on the shelf,\nin a grandmother\'s hand.', '"Keep counting until morning comes."'],
    'events.yule_sonja_gran.say': ['The fire on the peak is back.\n...I must tell that girl\nabout the morning.', 'Though I don\'t remember it\nall that well myself.'],
    'events.yule_sonja_gran.say_2': ['It was my mother who started\ncutting notches into that board.', '"Until morning comes," she said.\n...What was morning, now?\nSomething very bright, I\'m sure.'],
    'events.yule_hunter_bow.say.0': 'An old bow hangs on the wall.\nIts string is twisted from wolf hair.',
    'events.yule_base_in.say': ['This is our base!\nDon\'t tell the grown-ups.', 'The box in the back?\n...It\'s yours! A prize for\nguessing the password!'],
    'events.yule_base_drawing.say': ['A charcoal drawing on the wall:\na white dragon, a maiden carrying fire,\nand someone reading a book.', 'Below it, in clumsy letters,\nis written "storys."'],
    'events.yule_branch_desk.say': 'The desk drawer is empty.',
    'events.yule_branch_desk.say_2': ['In the desk drawer, a single letter\nwith a broken seal remains.', 'Addressed "To Mira."\nThere is no sender\'s name.'],
    'events.yule_branch_shelf.say': ['Copy ledgers line the shelf.\nEach has only a cover; inside, all white.', 'Only one has a half-written page:\n"Copied the festival book. ...Now I can\'t\ntell the village kids the story."'],
  });
})(window.RPG);
